package com.alsafa.native4.core;
import android.content.ContentValues;import android.database.Cursor;import android.database.sqlite.SQLiteDatabase;import com.alsafa.native4.sync.SyncOperation;import org.json.JSONArray;import org.json.JSONObject;import java.util.ArrayList;import java.util.List;import java.util.UUID;
/** Direct counter sale of a repair part/service. Invoice currency and collection currencies are independent. */
public final class DirectRepairPartSaleStore {private final CoreStore.DbProvider provider;private final String deviceId;public DirectRepairPartSaleStore(CoreStore.DbProvider provider,String deviceId){this.provider=provider;this.deviceId=deviceId;}
 public Result sell(String partId,int quantity,double unitPrice,double serviceFee,String currency,String paymentMethod)throws Exception{String cur=currency(currency),pay=req(paymentMethod,"طريقة الدفع").toUpperCase();List<SplitPaymentStore.Payment> legs=new ArrayList<>();double total=unitPrice*quantity+serviceFee;if(total>0&&!"LATER".equals(pay))legs.add(new SplitPaymentStore.Payment(total,cur,pay,drawer(pay)));return sellSplit(partId,quantity,unitPrice,serviceFee,cur,legs);}
 public Result sellSplit(String partId,int quantity,double unitPrice,double serviceFee,String invoiceCurrency,List<SplitPaymentStore.Payment> payments)throws Exception{String pid=req(partId,"قطعة الصيانة"),cur=currency(invoiceCurrency);if(quantity<=0)throw new IllegalArgumentException("الكمية يجب أن تكون أكبر من صفر");if(!Double.isFinite(unitPrice)||unitPrice<0||!Double.isFinite(serviceFee)||serviceFee<0)throw new IllegalArgumentException("السعر أو أجرة الخدمة غير صالحة");SQLiteDatabase db=provider.db();db.beginTransaction();try{String name;int before;double cost;try(Cursor c=db.rawQuery("SELECT name,quantity,unit_cost FROM repair_inventory WHERE part_id=? AND deleted_at IS NULL",new String[]{pid})){if(!c.moveToFirst())throw new IllegalArgumentException("قطعة الصيانة غير موجودة");name=c.getString(0);before=c.getInt(1);cost=c.getDouble(2);}if(before<quantity)throw new IllegalArgumentException("رصيد قطعة الصيانة غير كافٍ");int after=before-quantity;double partsTotal=unitPrice*quantity,total=partsTotal+serviceFee;long now=System.currentTimeMillis();String saleId="partsale-"+UUID.randomUUID();ContentValues p=new ContentValues();p.put("quantity",after);p.put("updated_at",now);if(db.update("repair_inventory",p,"part_id=? AND deleted_at IS NULL",new String[]{pid})!=1)throw new IllegalStateException("تعذر تحديث رصيد قطعة الصيانة");ContentValues mv=new ContentValues();mv.put("move_id",saleId+"-stock");mv.put("part_id",pid);mv.put("source_type","DIRECT_SALE");mv.put("source_id",saleId);mv.put("before_qty",before);mv.put("delta_qty",-quantity);mv.put("after_qty",after);mv.put("created_at",now);db.insertOrThrow("repair_inventory_moves",null,mv);FxSnapshotStore.Snapshot fx=FxSnapshotStore.capture(db,"REPAIR_PART_DIRECT",saleId,cur,total,now);JSONArray paymentJson=new JSONArray();if(payments!=null&&!payments.isEmpty())paymentJson=SplitPaymentStore.write(db,"REPAIR_PART_DIRECT",saleId,payments,now);double paidUsd=0;for(int i=0;i<paymentJson.length();i++)paidUsd+=paymentJson.getJSONObject(i).getDouble("usdAmount");if(paidUsd-fx.usdAmount>0.01)throw new IllegalArgumentException("مجموع الدفعات أكبر من قيمة البيع بعد تحويل العملات");JSONObject j=new JSONObject().put("saleId",saleId).put("saleType","REPAIR_PART_DIRECT").put("partId",pid).put("partName",name).put("quantity",quantity).put("beforeQty",before).put("afterQty",after).put("unitCost",cost).put("unitPrice",unitPrice).put("partsTotal",partsTotal).put("serviceFee",serviceFee).put("total",total).put("currency",cur).put("payments",paymentJson).put("paidUsdSnapshot",paidUsd).put("balanceUsdSnapshot",Math.max(0,fx.usdAmount-paidUsd)).put("fxUsdPerUnit",fx.usdPerUnit).put("totalUsdSnapshot",fx.usdAmount).put("fxCapturedAt",fx.capturedAt).put("createdAt",now);provider.enqueue(db,SyncOperation.create(SyncOperation.Kind.SALE_CREATE,saleId,j.toString(),deviceId));db.setTransactionSuccessful();return new Result(saleId,name,before,after,total,fx.usdAmount,cur,paymentJson.length(),paidUsd,Math.max(0,fx.usdAmount-paidUsd));}finally{db.endTransaction();}}
 private static String drawer(String pay){if("SHAM_CASH".equals(pay))return "SHAM_CASH";if("BANK".equals(pay))return "BANK";if("EXTERNAL".equals(pay))return "EXTERNAL";return "MAIN";}private static String req(String v,String l){String s=trim(v);if(s.isEmpty())throw new IllegalArgumentException(l+" مطلوب");return s;}private static String trim(String v){return v==null?"":v.trim();}private static String currency(String v){String x=trim(v).toUpperCase();return x.equals("TRY")||x.equals("SYP")?x:"USD";}
 public static final class Result{public final String saleId,partName,currency;public final int beforeQty,remainingQty,paymentCount;public final double total,totalUsd,paidUsd,balanceUsd;Result(String id,String n,int b,int r,double t,double u,String c,int pc,double pu,double bu){saleId=id;partName=n;beforeQty=b;remainingQty=r;total=t;totalUsd=u;currency=c;paymentCount=pc;paidUsd=pu;balanceUsd=bu;}}
}
